CREATE TABLE "ShopifyCustomerMirror" ("id" TEXT NOT NULL PRIMARY KEY,"shop" TEXT NOT NULL,"firstName" TEXT,"lastName" TEXT,"email" TEXT,"phone" TEXT,"numberOfOrders" INTEGER NOT NULL DEFAULT 0,"amountSpent" REAL NOT NULL DEFAULT 0,"currencyCode" TEXT NOT NULL DEFAULT 'INR',"tagsJson" TEXT NOT NULL DEFAULT '[]',"whatsappOptIn" BOOLEAN NOT NULL DEFAULT 0,"createdAtShopify" DATETIME,"updatedAtShopify" DATETIME,"syncedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
